# 1. plugins/-only edit is blocked and names the src/ path to edit.
GUARD_RC=0
GUARD_OUT=$(printf '%s\n' 'plugins/ork/skills/api-design/scripts/problem-detail-exceptions.py' | bash "$GUARD") || GUARD_RC=$?
if [[ $GUARD_RC -eq 1 ]] && grep -Fq 'src/skills/api-design/scripts/problem-detail-exceptions.py' <<< "$GUARD_OUT"; then
    log_pass "plugins/-only edit blocked; message names the src/ path"
else
