GUARD_OUT=$(printf '%s\n' \
    'plugins/ork/skills/api-design/scripts/problem-detail-exceptions.py' \
    'src/skills/api-design/scripts/problem-detail-exceptions.py' | bash "$GUARD") || GUARD_RC=$?
if [[ $GUARD_RC -eq 0 ]]; then
